// Capacity Growth Strategy (Implementation Defined, often 2x or 1.5x)
std::vector<int> v;
v.reserve(100);             // Capacity is >= 100
size_t initial_cap = v.capacity();
v.push_back(1);             // size() increases

// Forced Reallocation (If new_cap > capacity())
void efficient_growth(std::vector<T>& vec, size_t needed) {
    if (vec.capacity() < needed) {
        vec.reserve(std::max(needed, vec.capacity() * 2));
    }
}

// Shrink to Fit (Releases unused capacity)
std::vector<int> big_v(1000);
big_v.resize(10);
big_v.shrink_to_fit();      // capacity() == 10 (or less memory used)

// Swap trick for capacity reset (Guaranteed C++03+)
std::vector<T>().swap(v);   // v.capacity() == 0, v.size() == 0
